<?php declare(strict_types=1); require __DIR__ . '/_base.php'; ob_start(); $escape = static fn (string $value): string => htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); $activeNav = 'media'; ?>
<main class="admin-shell">
<?php require __DIR__ . '/_nav.php'; ?>
<section class="article-index"><p class="eyebrow">Media library</p><h1>Images</h1><form class="media-upload" method="post" action="<?= $path('/admin/media') ?>" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><label>Images<input type="file" name="image[]" accept="image/jpeg,image/png,image/gif,image/webp" multiple required></label><p class="muted">JPEG, PNG, GIF or WebP, up to 5 MB each. You can select multiple images.</p><button type="submit"><span class="icon" aria-hidden="true">upload</span>Upload image(s)</button></form><ul class="media-grid"><?php foreach ($media as $name): $url = '/media/' . rawurlencode($name); ?><li><img src="<?= $basePath ?><?= $url ?>" alt=""><strong><?= $escape($name) ?></strong><code>![](<?= $basePath ?><?= $url ?>)</code><button type="button" data-copy="![](<?= $basePath ?><?= $url ?>)"><span class="icon" aria-hidden="true">content_copy</span>Copy Markdown</button><form method="post" action="<?= $path('/admin/media/delete') ?>" onsubmit="return confirm('Permanently delete <?= $escape($name) ?>?');" style="margin:4px 0 0;"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="filename" value="<?= $escape($name) ?>"><button type="submit" class="secondary" style="color:#8b2f2f;border-color:#d8d1c5;font-size:12px;padding:5px 8px;width:100%;"><span class="icon" aria-hidden="true" style="font-size:15px;">delete</span>Delete</button></form></li><?php endforeach; ?></ul></section></main>
